head.b:skin:
/*
-----------------------------------------------
Theme Name   : Pesona Green Residence - Modular Blogger Landing Page
Version      : 2.0.0
Author       : Pesonaku
Design Style : Light Green & Emerald, High-Conversion Real Estate Layout
-----------------------------------------------
<Variable name="primaryColor" description="Warna Utama (Emerald)" type="color" default="#10b981" value="#10b981"/>
<Variable name="primaryDark" description="Warna Utama Gelap" type="color" default="#059669" value="#059669"/>
<Variable name="primaryLight" description="Warna Latar Lembut" type="color" default="#ecfdf5" value="#ecfdf5"/>
<Variable name="accentGold" description="Warna Aksen Promo" type="color" default="#f59e0b" value="#f59e0b"/>
<Variable name="darkText" description="Warna Teks Utama" type="color" default="#0f172a" value="#0f172a"/>
<Variable name="mutedText" description="Warna Teks Sekunder" type="color" default="#64748b" value="#64748b"/>
<Variable name="cardBg" description="Warna Background Card" type="color" default="#ffffff" value="#ffffff"/>
*/

:root {
  --primary: $(primaryColor);
  --primary-dark: $(primaryDark);
  --primary-light: $(primaryLight);
  --accent-gold: $(accentGold);
  --text-dark: $(darkText);
  --text-muted: $(mutedText);
  --bg-card: $(cardBg);
  --bg-page: #f8fafc;
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;
  --shadow-soft: 0 10px 25px -5px rgba(16, 185, 129, 0.08), 0 8px 10px -6px rgba(0, 0, 0, 0.04);
  --shadow-hover: 0 20px 30px -10px rgba(16, 185, 129, 0.18), 0 10px 15px -5px rgba(0, 0, 0, 0.05);
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-page);
  color: var(--text-dark);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: all 0.25s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 20px;
  padding-right: 20px;
}

.section-pad {
  padding-top: 80px;
  padding-bottom: 80px;
}

.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 50px auto;
}

.badge-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  background: var(--primary-light);
  color: var(--primary-dark);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
  margin-bottom: 14px;
  border: 1px solid rgba(16, 185, 129, 0.2);
}

.section-title {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--text-dark);
  letter-spacing: -0.02em;
  line-height: 1.25;
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.05rem;
  color: var(--text-muted);
}

/* BUTTONS */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-weight: 700;
  font-size: 0.95rem;
  padding: 13px 26px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: #ffffff !important;
  box-shadow: 0 10px 20px rgba(16, 185, 129, 0.28);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 15px 25px rgba(16, 185, 129, 0.38);
  filter: brightness(1.05);
}

.btn-outline {
  background: #ffffff;
  color: var(--primary-dark) !important;
  border: 2px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.85rem;
}

/* NAVBAR */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(226, 232, 240, 0.85);
  transition: all 0.3s ease;
}

.nav-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 78px;
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--text-dark);
  letter-spacing: -0.02em;
}

.nav-brand-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--primary), var(--primary-dark));
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-weight: 800;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-link {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-muted);
}

.nav-link:hover {
  color: var(--primary-dark);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.nav-profile-pic {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid var(--primary);
  object-fit: cover;
}

.hamburger-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1.6rem;
  color: var(--text-dark);
}

/* HERO BANNER COVER */
.hero-section {
  position: relative;
  padding-top: 120px;
  padding-bottom: 70px;
  background: radial-gradient(circle at 10% 20%, rgba(236, 253, 245, 0.8) 0%, rgba(248, 250, 252, 1) 70%);
}

.hero-banners-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 30px;
  align-items: stretch;
}

.hero-main-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 440px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 40px;
  box-shadow: 0 20px 40px -10px rgba(16, 185, 129, 0.22);
}

.hero-main-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 1;
}

.hero-main-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(15, 23, 42, 0.92) 0%, rgba(15, 23, 42, 0.4) 60%, transparent 100%);
  z-index: 2;
}

.hero-main-content {
  position: relative;
  z-index: 3;
  color: #ffffff;
}

.hero-main-content h2 {
  font-size: 2.2rem;
  font-weight: 800;
  line-height: 1.25;
  margin-bottom: 14px;
}

.hero-main-content p {
  font-size: 1.05rem;
  color: #e2e8f0;
  margin-bottom: 24px;
  max-width: 600px;
}

.hero-side-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
  padding: 32px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.hero-side-card figure {
  height: 200px;
  border-radius: var(--radius-md);
  overflow: hidden;
  margin-bottom: 20px;
}

.hero-side-card figure img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-side-card h3 {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--text-dark);
  margin-bottom: 10px;
}

.hero-side-card p {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-bottom: 20px;
  line-height: 1.6;
}

/* MODULAR ABOUT / KEUNGGULAN SECTION */
.about-modular-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.about-modular-item {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 24px;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.about-modular-item:hover {
  transform: translateY(-5px);
  border-color: var(--primary);
  box-shadow: var(--shadow-hover);
}

.about-modular-thumb {
  width: 100%;
  height: 150px;
  border-radius: var(--radius-sm);
  object-fit: cover;
}

.about-modular-item h3 {
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--text-dark);
}

.about-modular-item p {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* MODULAR SERVICE / TYPE RUMAH SECTION */
.service-modular-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 28px;
}

.service-modular-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: all 0.3s ease;
}

.service-modular-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-hover);
  border-color: rgba(16, 185, 129, 0.4);
}

.service-modular-thumb {
  width: 100%;
  height: 220px;
  object-fit: cover;
}

.service-modular-body {
  padding: 24px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.service-modular-body h3 {
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--text-dark);
  margin-bottom: 10px;
}

.service-modular-body p {
  font-size: 0.95rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 20px;
}

/* OFFER PRICING TABLE (SEPERTI PESONAKAHURIPAN.ORG) */
.pricing-wrap {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 30px;
  max-width: 900px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 2px solid #e2e8f0;
  padding: 36px 30px;
  box-shadow: var(--shadow-soft);
  position: relative;
  transition: all 0.3s ease;
  display: flex;
  flex-direction: column;
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 20px 35px -10px rgba(16, 185, 129, 0.25);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 800;
  text-transform: uppercase;
}

.pricing-card h3 {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 8px;
  color: var(--text-dark);
}

.pricing-price {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--primary-dark);
  margin-bottom: 6px;
}

.pricing-subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px dashed #e2e8f0;
}

.pricing-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 30px;
}

.pricing-features li {
  font-size: 0.95rem;
  color: var(--text-dark);
  display: flex;
  align-items: center;
  gap: 10px;
}

.pricing-features li strong {
  color: var(--primary-dark);
}

/* GALLERY GRID WITH FANCYBOX */
.gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 18px;
}

.gallery-item {
  position: relative;
  height: 220px;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
}

.gallery-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.gallery-item:hover img {
  transform: scale(1.08);
}

.gallery-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(15, 23, 42, 0.8) 0%, transparent 60%);
  display: flex;
  align-items: flex-end;
  padding: 16px;
  color: #fff;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.gallery-item:hover .gallery-overlay {
  opacity: 1;
}

/* MODULAR FAQ ACCORDION */
.faq-accordion-wrap {
  max-width: 820px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.faq-accordion-item {
  background: var(--bg-card);
  border: 1px solid #e2e8f0;
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color 0.25s ease;
}

.faq-accordion-item.active {
  border-color: var(--primary);
}

.faq-accordion-header {
  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--text-dark);
  user-select: none;
}

.faq-accordion-icon {
  font-size: 1.1rem;
  transition: transform 0.3s ease;
  color: var(--primary);
}

.faq-accordion-item.active .faq-accordion-icon {
  transform: rotate(180deg);
}

.faq-accordion-body {
  padding: 0 24px;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.7;
}

.faq-accordion-item.active .faq-accordion-body {
  padding: 0 24px 22px 24px;
  max-height: 250px;
}

/* MODULAR REVIEW / TESTIMONI SECTION */
.review-modular-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.review-modular-card {
  background: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 28px;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.review-stars {
  color: #f59e0b;
  font-size: 1.1rem;
}

.review-text {
  font-size: 0.95rem;
  color: var(--text-dark);
  line-height: 1.7;
  font-style: italic;
  flex-grow: 1;
}

.review-author-wrap {
  display: flex;
  align-items: center;
  gap: 14px;
  border-top: 1px dashed #e2e8f0;
  padding-top: 14px;
}

.review-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
}

.review-name {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--text-dark);
}

.review-unit {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* KONTAK & LOKASI */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 36px;
  align-items: center;
}

.contact-info-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 36px;
  border: 1px solid #e2e8f0;
  box-shadow: var(--shadow-soft);
}

.map-wrap {
  height: 380px;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
  border: 1px solid #e2e8f0;
}

.map-wrap iframe {
  width: 100%;
  height: 100%;
  border: none;
}

/* FOOTER & SOSIAL MEDIA */
.footer {
  background: #0f172a;
  color: #94a3b8;
  padding-top: 70px;
  padding-bottom: 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 50px;
}

.footer-brand h3 {
  color: #fff;
  font-size: 1.4rem;
  font-weight: 800;
  margin-bottom: 14px;
}

.footer-links h4 {
  color: #fff;
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 18px;
}

.footer-links ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a:hover {
  color: var(--primary);
}

.social-icons {
  display: flex;
  gap: 12px;
  margin-top: 18px;
}

.social-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: #1e293b;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #cbd5e1;
  transition: all 0.25s ease;
}

.social-icon:hover {
  background: var(--primary);
  color: #fff;
  transform: translateY(-3px);
}

.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid #1e293b;
  text-align: center;
  font-size: 0.85rem;
}

/* FLOATING INTERACTIVE CHAT (SEPERTI PESONAKAHURIPAN.ORG) */
.floating-chat-container {
  position: fixed;
  bottom: 25px;
  right: 25px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.floating-chat-box {
  background: #ffffff;
  border-radius: var(--radius-lg);
  box-shadow: 0 20px 40px -10px rgba(0, 0, 0, 0.25);
  border: 1px solid #e2e8f0;
  width: 320px;
  overflow: hidden;
  margin-bottom: 12px;
  display: none;
  animation: fadeInUp 0.3s ease;
}

.floating-chat-box.active {
  display: block;
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: translateY(0); }
}

.chat-box-header {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: #ffffff;
  padding: 16px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.chat-header-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  object-fit: cover;
}

.chat-header-info h4 {
  font-size: 1rem;
  font-weight: 700;
}

.chat-header-info small {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  opacity: 0.9;
}

.chat-header-info small::before {
  content: '';
  display: inline-block;
  width: 8px;
  height: 8px;
  background: #4ade80;
  border-radius: 50%;
}

.chat-box-body {
  padding: 20px;
  background: #f8fafc;
}

.chat-bubble {
  background: #ffffff;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  border: 1px solid #e2e8f0;
  font-size: 0.9rem;
  color: var(--text-dark);
  margin-bottom: 16px;
  line-height: 1.5;
}

.chat-form {
  display: flex;
  gap: 8px;
}

.chat-input {
  flex-grow: 1;
  padding: 10px 14px;
  border: 1px solid #cbd5e1;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  outline: none;
  font-family: inherit;
}

.chat-input:focus {
  border-color: var(--primary);
}

.chat-send-btn {
  background: var(--primary);
  color: #ffffff;
  border: none;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.2s ease;
}

.chat-send-btn:hover {
  background: var(--primary-dark);
}

.floating-trigger-btn {
  background: #25d366;
  color: #ffffff;
  padding: 12px 22px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 0.95rem;
  box-shadow: 0 10px 25px rgba(37, 211, 102, 0.4);
  cursor: pointer;
  border: none;
  transition: all 0.3s ease;
}

.floating-trigger-btn:hover {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 15px 30px rgba(37, 211, 102, 0.5);
}

/* RESPONSIVE DESIGN */
@media (max-width: 992px) {
  .hero-banners-grid, .contact-grid {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute;
    top: 78px;
    left: 0;
    right: 0;
    background: #ffffff;
    flex-direction: column;
    padding: 24px;
    border-bottom: 1px solid #e2e8f0;
    box-shadow: 0 15px 25px rgba(0,0,0,0.05);
    gap: 18px;
  }
  .nav-links.mobile-open {
    display: flex;
  }
  .hamburger-btn {
    display: block;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

b:includable.script:
// URL Web App Google Script untuk menangkap Lead Nama & WA (Opsional)
const $googleSheetScriptUrl = "";
const $marketingWhatsApp = "6281234567890";

body.script:
document.addEventListener('DOMContentLoaded', function() {
  // 1. Inisialisasi Fancybox untuk Galeri
  if (typeof Fancybox !== 'undefined') {
    Fancybox.bind('[data-fancybox]', {});
  }

  // 2. Mobile Hamburger Menu Toggle
  const hamburgerBtn = document.getElementById('hamburger-toggle');
  const navMenu = document.getElementById('nav-menu');
  if (hamburgerBtn && navMenu) {
    hamburgerBtn.addEventListener('click', function() {
      navMenu.classList.toggle('mobile-open');
    });
    navMenu.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => navMenu.classList.remove('mobile-open'));
    });
  }

  // 3. Parsing Format Link Ganda (Label|URL) pada Widget Image
  document.querySelectorAll('.parsed-link').forEach(link => {
    const rawHref = link.getAttribute('href') || '';
    if (rawHref.includes('|')) {
      const parts = rawHref.split('|');
      link.textContent = parts[0].trim();
      link.setAttribute('href', parts[1].trim());
    }
  });

  // 4. FAQ Accordion Toggle
  document.querySelectorAll('.faq-accordion-header').forEach(header => {
    header.addEventListener('click', function() {
      const item = this.closest('.faq-accordion-item');
      const isActive = item.classList.contains('active');
      document.querySelectorAll('.faq-accordion-item').forEach(i => i.classList.remove('active'));
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // 5. Floating Chat Toggle
  const triggerBtn = document.getElementById('floating-trigger-btn');
  const chatBox = document.getElementById('floating-chat-box');
  if (triggerBtn && chatBox) {
    triggerBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      chatBox.classList.toggle('active');
    });
    document.addEventListener('click', function(e) {
      if (!chatBox.contains(e.target) && e.target !== triggerBtn) {
        chatBox.classList.remove('active');
      }
    });
  }

  // 6. SweetAlert2 Lead Capture + WhatsApp + Google Sheets
  const leadForm = document.getElementById('quick-lead-form');
  if (leadForm) {
    leadForm.addEventListener('submit', function(e) {
      e.preventDefault();
      const userMsg = document.getElementById('quick-message-input').value;
      const phone = (typeof $marketingWhatsApp !== 'undefined' && $marketingWhatsApp) ? $marketingWhatsApp : '6281234567890';

      Swal.fire({
        title: 'Isi Data Diri Anda',
        text: 'Kami akan segera menghubungi dan mengirimkan brosur ke WhatsApp Anda.',
        html:
          '<input id="swal-lead-name" class="swal2-input" placeholder="Nama Lengkap">' +
          '<input id="swal-lead-wa" class="swal2-input" placeholder="Nomor WhatsApp (contoh: 0812xxx)" type="tel">',
        focusConfirm: false,
        showCancelButton: true,
        confirmButtonText: 'Kirim via WhatsApp',
        cancelButtonText: 'Batal',
        confirmButtonColor: '#10b981',
        preConfirm: () => {
          const name = document.getElementById('swal-lead-name').value;
          const wa = document.getElementById('swal-lead-wa').value;
          if (!name || !wa) {
            Swal.showValidationMessage('Nama dan Nomor WhatsApp wajib diisi');
            return false;
          }
          return { name: name, wa: wa };
        }
      }).then((result) => {
        if (result.isConfirmed) {
          const clientName = result.value.name;
          const clientWa = result.value.wa;

          // Optional Webhook Google Sheets
          if (typeof $googleSheetScriptUrl !== 'undefined' && $googleSheetScriptUrl && $googleSheetScriptUrl.startsWith('http')) {
            const sheetUrl = $googleSheetScriptUrl + '?name=' + encodeURIComponent(clientName) + '&wa=' + encodeURIComponent("'" + clientWa) + '&message=' + encodeURIComponent(userMsg);
            fetch(sheetUrl, { mode: 'no-cors' }).catch(err => console.log(err));
          }

          // Redirect ke WhatsApp
          const finalMessage = "Halo Marketing,\n\nNama: " + clientName + "\nNo WhatsApp: " + clientWa + "\nPesan: " + userMsg + "\n\nReferensi: " + window.location.href;
          const waUrl = "https://api.whatsapp.com/send?phone=" + phone + "&text=" + encodeURIComponent(finalMessage);
          window.open(waUrl, '_blank');

          document.getElementById('quick-message-input').value = '';
          if (chatBox) chatBox.classList.remove('active');
        }
      });
    });
  }
});
